import{_ as o,o as c,c as d,ai as p}from"./chunks/framework.DAbPic9L.js";const h=JSON.parse('{"title":"客户端浏览器面试题集（待优化）","description":"","frontmatter":{},"headers":[],"relativePath":"interviews/browser.md","filePath":"interviews/browser.md","lastUpdated":1783097192000}'),l={name:"interviews/browser.md"};function i(a,e,t,r,n,s){return c(),d("div",null,[...e[0]||(e[0]=[p('<h1 id="客户端浏览器面试题集-待优化" tabindex="-1">客户端浏览器面试题集（待优化） <a class="header-anchor" href="#客户端浏览器面试题集-待优化" aria-label="Permalink to &quot;客户端浏览器面试题集（待优化）&quot;">​</a></h1><p>文/晨风不可依米</p><br><h2 id="如何理解浏览器的进程模型" tabindex="-1">如何理解浏览器的进程模型 <a class="header-anchor" href="#如何理解浏览器的进程模型" aria-label="Permalink to &quot;如何理解浏览器的进程模型&quot;">​</a></h2><p><strong>基本概念</strong></p><ul><li><p>进程：应用程序运行时管理自身运行的内存空间；进程之间相互独立，进程通信需遵循协议约定。</p></li><li><p>线程：扮演执行程序代码的系统角色；进程里至少存在一个线程（主线程），保证进程不浪费空间。若主线程忙不过来，可开辟多线程（负责执行特定任务），提高程序的并发性。</p></li><li><p>特别注意</p><ul><li>浏览器是一个多进程多线程的应用程序；每一个标签页都是个独立的进程，保证标签页不会造成连环崩溃现象。</li><li>浏览器的运行，会自动开启多个进程，以维持浏览器的高效稳定执行。浏览器常见进程有浏览器进程、网络进程、渲染进程，以及其它进程等。</li></ul></li></ul><p><strong>浏览器进程模型</strong></p><ol><li>浏览器进程：负责浏览器界面显示、用户交互、以及管理子进程等；如标题、地址栏、导航行为（前进、后退、刷新）、书签、<code>Cookie</code>管理等。</li><li>网络进程：负责管理网络资源；内部会通过多个线程来处理不同的网络任务（加载、预解析网络资源等）。</li><li>渲染进程（前端重点）：自动开启渲染主线程，负责解析、执行<code>HTML</code>、<code>CSS</code>、<code>JavaScript</code>代码，并渲染展示页面内容。每一个浏览器标签页，就是一个新的渲染进程，互不干扰。</li><li>其它进程等。</li></ol><h2 id="如何理解浏览器的事件循环机制" tabindex="-1">如何理解浏览器的事件循环机制 <a class="header-anchor" href="#如何理解浏览器的事件循环机制" aria-label="Permalink to &quot;如何理解浏览器的事件循环机制&quot;">​</a></h2><p>渲染主线程主要负责处理的任务包括但不限于解析<code>HTML</code>、<code>CSS</code>、<code>JavaScript</code>代码，计算样式，几何布局，处理图层、帧绘制，执行<code>JavaScript</code>代码，事件处理函数、定时器回调函数等。</p><p>由于渲染主线程需要处理以上任务内容，但需保证任务执行的优先级；因此引入事件循环（<code>Event Loop</code>）机制解决任务调度问题；本质上是通过消息队列、循环检出任务执行来解决问题。</p><p><strong>事件循环机制流程</strong></p><ol><li>标签页（渲染进程）启动，渲染主线程进入无限循环；</li><li>在每次循环过程中检测是否存在任务，存在则从消息队列里取出并执行，否则进入休眠状态，并等待下次检出激活执行。</li><li>执行取出任务时，可能产生新任务，新任务就添加到消息队列里；如此往复，直到本次循环结束。</li><li>其它线程可能产生新任务，也会添加到消息队列里；如用户交互的事件处理，会被打包成任务添加到消息队列。</li><li>事件循环（消息循环）机制的引入，让渲染主线程的任务执行，变得有条不紊，高效执行。</li></ol><p>虽然事件循环机制解决了任务有序调度顺序问题，但由于渲染主线程存在某些任务无法理解处理（执行过程太耗时），渲染主线程会造成阻塞，浪费等待过程的渲染时间。而渲染主线程无论如何都不能造成阻塞，否则引起页面卡顿、白屏等问题；因此引入异步编程模型，解决任务调度优先级问题。</p><p><strong>同步与异步的区别</strong></p><p><code>JavaScript</code>是一门单线程的编程语言，在浏览器渲染进程中，渲染主线程只有一个。渲染主线程承担繁多复杂的工作任务。若使用同步方式执行任务，渲染主线程会产生阻塞、等待，导致事件循环中的任务无法正常执行；一方面浪费渲染主线程所等待期间的时间，另一方面浏览器所造成白屏、卡死等问题，会导致不好的用户体验。因此，引入异步编程模型，渲染主线程将无法立即处理的任务交给其它线程处理，并结束当前任务，继续执行下一个任务。当其它线程完成后，会将事件回调打包成任务并加入到消息队列里，等待渲染主线程调度执行。如此，在异步编程下，渲染主线程永不阻塞，最大限度保证单线程的流畅运行。</p><p><strong><code>W3C</code>规范说明</strong></p><ul><li>渲染主线程的任务没有优先级，遵循消息队列的“先进先出”的顺序执行。</li><li>消息队列有优先级，这是<code>W3C</code>规范说明，每个任务都有一个任务类型，不同任务类型的任务存放在不同的消息队列里；另外，规定浏览器存在一个微队列，微队列的任务优先于所有其它任务执行。（谷歌浏览器的消息队列优先级：微队列 &gt; 交互队列 &gt; 延时队列 &gt; 其它队列）</li><li>特别注意：老版本的浏览器概念（微任务、宏任务）已不再适应现代浏览器的实现流程，而是将宏任务拆分成不同种类的任务队列，以适应现代浏览器的调度需要。</li></ul><p><strong>源码流程分析技巧</strong></p><ol><li>渲染主线程执行全局<code>JS</code>程序代码，根据不同任务类型，将函数任务添加到对应的消息队列里，并继续往下执行。</li><li>全局<code>JS</code>执行到底，渲染主线程再根据不同任务类型的优先级，依次执行消息队列里的任务。</li></ol><p><strong>个人总结</strong></p><ol><li><code>JS</code>是一门单线程的编程语言，浏览器渲染主线程要负责解析程序代码、排版几何布局、构建图层分层、帧率渲染页面，执行全局<code>JS</code>程序、处理交互事件、定时器回调等复杂多样的任务。</li><li>通过事件循环机制，渲染主线程开启无限循环模式，利用消息队列将任务逐个取出，保证渲染主线程任务调度有序执行。但渲染主线程可能存在无法立即处理的任务，导致浏览器渲染阻塞产生白屏、卡死等问题，造成不好的用户体验。</li><li>通过异步编程模型，渲染主线程将无法立即处理的任务交给其它线程处理，并结束当前任务，继续执行下一个任务。当其它线程完成后，会将事件回调打包成任务并加入到渲染主线程的消息队列里，等待调度执行。另外，<code>W3C</code>官方规范说明，每个任务有不同的任务类型，根据任务类型存储在不同的消息队列里；且规定浏览器必须存在个微队列，微队列任务优先于其它所有队列任务执行。也就是说，消息队列有优先级；如此，渲染主线程永不阻塞，最大限度保证单线程的流畅运行。</li></ol><h2 id="如何理解定时器执行所产生的偏差原因" tabindex="-1">如何理解定时器执行所产生的偏差原因 <a class="header-anchor" href="#如何理解定时器执行所产生的偏差原因" aria-label="Permalink to &quot;如何理解定时器执行所产生的偏差原因&quot;">​</a></h2><ol><li>计算机硬件没有原子钟，而是利用操作系统的时间函数；因此存在偏差。</li><li><code>W3C</code>规范说明，定时器嵌套<code>5</code>层结构后会产生<code>4</code>毫秒的额定偏差。</li><li>根据事件循环机制和异步编程模型，定时器所属的延时队列优先级在微队列和交互队列之后，需等待微队列和交互队列执行完毕后才会执行。</li></ol><h2 id="如何理解渲染主线程的工作内容" tabindex="-1">如何理解渲染主线程的工作内容 <a class="header-anchor" href="#如何理解渲染主线程的工作内容" aria-label="Permalink to &quot;如何理解渲染主线程的工作内容&quot;">​</a></h2><p>浏览器网络线程收到<code>HTML</code>文档后，产生渲染任务，并加入到渲染主线程的消息队列里，等待调度执行。在事件循环机制下，渲染主线程取出渲染任务，开启渲染流程；细节如下：</p><ol><li><p>解析<code>HTML</code>文档</p><p>在解析过程中，为了提高效率，浏览器快速扫描抓取外部资源链接（<code>link</code>、<code>script</code>），并率先下载相关资源。</p><p>解析流程遵循“遇到<code>CSS</code>解析<code>CSS</code>，遇到<code>JS</code>执行<code>JS</code>代码”规则。</p><p>解析到<code>link</code>位置内容，渲染主线程不会等待，而是开启预解析线程来解析<code>CSS</code>，这也是渲染主线程不会阻塞<code>CSS</code>的根本原因。</p><p>解析到<code>script</code>位置内容，渲染主线程会暂停，等待<code>JS</code>执行完毕后，才会继续解析；这是因为<code>JS</code>代码可能修改<code>DOM</code>结构所致，也是渲染主线程会阻塞<code>JS</code>的根本原因。</p><p>解析<code>HTML</code>文档完毕，会返回<code>DOM</code>树和<code>CSSOM</code>树。<code>DOM</code>树可通过<code>document.documentElement</code>访问；<code>CSSOM</code>树可通过<code>document.styleSheets</code>访问。</p></li><li><p>层叠样式计算</p><p>渲染主线程遍历<code>DOM</code>树，依次为树中的每个节点计算出最终样式。</p><p><span class="text-red">样式规则计算过程</span></p><p>a. 确定声明值：预设值、默认值以及自定义明确值；优先将预设值转换为明确值。</p><p>b. 样式层叠规则：根据样式规则的重要性（样式表来源）、优先级（选择器权重）以及源次序（书写顺序）决定最终样式规则。</p><p>c. 样式继承规则：样式没有值，且样式属性有继承能力，可从上层元素继承。</p><p>d. 沿用默认值：样式没有值，且无法继承其它样式规则；沿用默认值（浏览器）。</p><p><code>CSS</code>属性值的计算过程，会优先将预设值转换为明确值，并通过有值不冲突确定部份最终样式规则，将有值冲突（多次赋值）的样式规则按照样式重要性（样式表来源）、优先级（选择器权重）以及源次序（书写顺序）计算最终样式值。对于无值样式规则，会通过样式继承和样式默认值确定最终样式值。</p><p>详细内容可参见<a href="/blog/interviews/css.html">界面样式规则（CSS）面试题集</a>章节。</p></li><li><p>构建几何布局</p><p>渲染主线程遍历<code>DOM</code>树每一个节点，计算出每个节点的几何信息；如节点的宽高、包含块的相对位置。</p><p>设置<code>dispaly: none</code>的节点不产生几何信息，在<code>Layout</code>布局树中不可见。使用伪类元素，在<code>DOM</code>树不存在伪元素节点，但在<code>Layout</code>布局树中拥有几何信息；因此，就造成了<code>Layout</code>布局树和<code>DOM</code>树的结构并不是一一对应的。</p><p>另外，<code>Layout</code>布局树的元素，行盒和块盒不能相邻，且内容必须在行盒中；浏览器会通过匿名块盒或匿名行盒自动补全。</p><p><span class="text-red">回流（<code>reflow</code>）在此阶段，会重新计算节点的几何信息，并对后续流程全走一遍。</span></p></li><li><p>图层分层堆叠</p><p>渲染主线程使用一套复杂的策略对整个布局树进行图层分层。使得在未来图层内容发生变化，仅重新处理该层内容，从而提高效率。</p><p>滚动条、堆叠上下文、<code>transform</code>、<code>opacity</code>等样式都会影响到分层结果；另外，可通过指定<code>will-change</code>属性细粒控制分层结果。</p></li><li><p>绘制图层指令</p><p>渲染主线程为每个图层单独产生绘制指令集，用于描述这一层如何画出来。</p><p>当完成绘制后，渲染主线程将每个图层的绘制信息提交给合成线程。</p><p><span class="text-red">渲染主线程到此为止，剩余工作交由合成线程完成。</span></p><p><span class="text-red">重绘（<code>repaint</code>）在此阶段，仅对差异图层重新生成图层绘制指令集。</span></p></li><li><p>分块切割内容</p><p>合成线程通过多线程并发对每个图层进行分块，划分为更多小区域内容块。</p></li><li><p>内容光栅成块</p><p>合成线程将分块内容提交给<code>CPU</code>进程，优先处理屏幕显示区分块内容，以极高速度完成光栅化，最终产生位图。</p></li><li><p>绘画位图内容</p><p>合成线程拿到每个图层的位图，生成一个个指引信息；每个指引信息会标识位图应该画到屏幕的某个位置，以及旋转、缩放等变形操作。</p><p>特别注意：标签节点的变形操作（<code>transform</code>）在这一阶段发生，不发生在渲染主线程，这就是<code>transform</code>为什么效率高的原因。</p></li><li><p>显示像素界面</p><p>合成线程将每个指引信息提交给<code>GPU</code>进程，<code>GPU</code>进程将图层的像素信息绘制到屏幕上。</p></li></ol><h2 id="如何理解回流-reflow-与重绘-repaint" tabindex="-1">如何理解回流（<code>reflow</code>）与重绘(<code>repaint</code>) <a class="header-anchor" href="#如何理解回流-reflow-与重绘-repaint" aria-label="Permalink to &quot;如何理解回流（`reflow`）与重绘(`repaint`)&quot;">​</a></h2><p>回流（<code>reflow</code>）的本质是节点的几何信息（尺寸、位置）发生变化，触发重新计算构建<code>Layout</code>布局树；后续流程全走一遍。为了提交渲染效率，浏览器会将多次设置操作打包封装成一次事件处理，等待渲染主线程事件循环机制调度执行。</p><p>重绘（<code>repaint</code>）的本质是节点的非几何信息（色差、显隐）发生变化，触发重新生成图层绘制指令集。而这一过程，只对局部图层进行重新绘制，不会影响其它图层。</p>',30)])])}const u=o(l,[["render",i]]);export{h as __pageData,u as default};
